11: use types::{pay_core_types, Currency, Money, PaymentMethod, PaymentTx, TxStatus};
12: 
13: fn test_currency_parsing_and_properties() {
14:     assert_eq!(Currency::from_code("EUR"), Some(Currency::Eur));
15:     assert_eq!(Currency::from_code("USD"), Some(Currency::Usd));
16:     assert_eq!(Currency::from_code("GBP"), Some(Currency::Gbp));
17:     assert_eq!(Currency::from_code("JPY"), Some(Currency::Jpy));
18:     assert_eq!(Currency::from_code("UNKNOWN"), None);
19: 
20:     assert_eq!(Currency::Eur.code(), "EUR");
21:     assert_eq!(Currency::Usd.code(), "USD");
22:     assert_eq!(Currency::Gbp.code(), "GBP");
23:     assert_eq!(Currency::Jpy.code(), "JPY");
24: 
25:     assert_eq!(Currency::Eur.minor_unit_decimals(), 2);
26:     assert_eq!(Currency::Jpy.minor_unit_decimals(), 0);
27: }
28: 
29: fn test_money_arithmetic() {
30:     let eur_one = Money::new(5_000, Currency::Eur);
31:     let eur_two = Money::new(2_500, Currency::Eur);
32:     let sum = eur_one.add(&eur_two).expect("valid addition");
33:     assert_eq!(sum.amount_cents, 7_500);
34:     assert_eq!(sum.currency, Currency::Eur);
35: 
36:     let diff = eur_one.sub(&eur_two).expect("valid subtraction");
37:     assert_eq!(diff.amount_cents, 2_500);
38: 
39:     let usd = Money::new(1_000, Currency::Usd);
40:     assert!(eur_one.add(&usd).is_err());
41:     assert!(eur_one.sub(&usd).is_err());
42: 
43:     let too_large = Money::new(10_000, Currency::Eur);
44:     assert!(eur_one.sub(&too_large).is_err());
45: }
46: 
47: fn test_payment_tx_lifecycle() {
48:     let mut tx = PaymentTx::new(1001, 555, 75_000, Currency::Usd);
49:     assert_eq!(tx.id, 1001);
50:     assert_eq!(tx.account_id, 555);
51:     assert_eq!(tx.amount_cents, 75_000);
52:     assert_eq!(tx.currency, Currency::Usd);
53:     assert_eq!(tx.status, TxStatus::Initiated);
54:     assert!(!tx.status.is_terminal());
55: 
56:     tx.settle();
57:     assert_eq!(tx.status, TxStatus::Settled);
58:     assert!(tx.is_settled());
59:     assert!(tx.status.is_terminal());
60: 
61:     let mut rejected_tx = PaymentTx::new(1002, 555, 90_000, Currency::Gbp);
62:     rejected_tx.reject();
63:     assert_eq!(rejected_tx.status, TxStatus::Rejected);
64:     assert!(!rejected_tx.is_settled());
65:     assert!(rejected_tx.status.is_terminal());
66: }
67: 
68: fn test_payment_methods() {
69:     let card = PaymentMethod::CreditCard;
70:     let bank = PaymentMethod::BankTransfer;
71:     let wire = PaymentMethod::InstantWire;
72:     assert_ne!(card, bank);
73:     assert_ne!(bank, wire);
74: }
