15: fn test_auto_approval_flow() {
16:     let mut machine = ApprovalStateMachine::new(100_000);
17:     let state = machine.evaluate_tx(501, 75_000, 1_700_000_100);
18:     assert_eq!(state, PaymentState::Approved);
19: 
20:     let settle_res = machine.apply_event(
21:         501,
22:         state,
23:         PaymentEvent::Settle,
24:         1_700_000_200,
25:     );
26:     assert_eq!(settle_res, Ok(PaymentState::Settled));
27: 
28:     let logs = machine.audit_entries_for(501);
29:     assert_eq!(logs.len(), 2);
30:     assert_eq!(logs[0].from_state, PaymentState::Initiated);
31:     assert_eq!(logs[0].to_state, PaymentState::Approved);
32:     assert_eq!(logs[1].from_state, PaymentState::Approved);
33:     assert_eq!(logs[1].to_state, PaymentState::Settled);
34: }
35: 
36: fn test_manual_review_and_rejection_flow() {
37:     let mut machine = ApprovalStateMachine::new(50_000);
38:     let state = machine.evaluate_tx(701, 120_000, 1_700_000_300);
39:     assert_eq!(state, PaymentState::PendingReview);
40: 
41:     let reject_res = machine.apply_event(
42:         701,
43:         state,
44:         PaymentEvent::Reject("Suspicious velocity profile".to_string()),
45:         1_700_000_400,
46:     );
47:     assert_eq!(reject_res, Ok(PaymentState::Rejected));
48: 
49:     let logs = machine.audit_entries_for(701);
50:     assert_eq!(logs.len(), 2);
51:     assert_eq!(logs[0].to_state, PaymentState::PendingReview);
52:     assert_eq!(logs[1].to_state, PaymentState::Rejected);
53: }
54: 
55: fn test_invalid_transitions_rejected() {
56:     let mut machine = ApprovalStateMachine::new(50_000);
57:     let illegal_settle = machine.apply_event(
58:         801,
59:         PaymentState::Initiated,
60:         PaymentEvent::Settle,
61:         1_700_000_500,
62:     );
63:     assert!(illegal_settle.is_err());
64: }
65: 
66: fn test_compliance_escalation_flow() {
67:     let mut machine = ApprovalStateMachine::new(50_000);
68:     let state = machine.evaluate_tx(901, 150_000, 1_700_000_600);
69:     assert_eq!(state, PaymentState::PendingReview);
70: 
71:     let review_queued = machine.apply_event(
72:         901,
73:         PaymentState::Initiated,
74:         PaymentEvent::RequestReview,
75:         1_700_000_650,
76:     );
77:     assert_eq!(review_queued, Ok(PaymentState::PendingReview));
78: 
79:     let approved = machine.apply_event(
80:         901,
81:         PaymentState::PendingReview,
82:         PaymentEvent::Approve,
83:         1_700_000_700,
84:     );
85:     assert_eq!(approved, Ok(PaymentState::Approved));
86: }
